import { hashPassword, passwordErrors, verifyPassword } from './password';
import { currentTotp, generateTotpSecret, verifyTotp, verifyTotpAt } from './totp';

describe('admin passwords', () => {
  it('verifies a Devise-style $2a$ bcrypt hash', async () => {
    // Generated by Ruby's bcrypt gem (BCrypt::Password.create("secret123", cost: 4)), as Devise does.
    const deviseHash = '$2a$04$aEX3E3SpgSkH/LW7CJH.puiX6W7gGQNNJ0Z3i/qm49cfgsfih/mUO';
    expect(await verifyPassword('secret123', deviseHash)).toBe(true);
    expect(await verifyPassword('wrong', deviseHash)).toBe(false);
  });

  it('creates hashes that use the same bcrypt format', async () => {
    const ownHash = await hashPassword('secret123', 4);
    expect(ownHash.startsWith('$2')).toBe(true);
    expect(await verifyPassword('secret123', ownHash)).toBe(true);
  });

  it('rejects empty or malformed hashes', async () => {
    expect(await verifyPassword('x', '')).toBe(false);
    expect(await verifyPassword('x', 'plain')).toBe(false);
  });

  it('applies the Rails password rules', () => {
    expect(passwordErrors('abc', 'abc')).toContain('Password is too short (minimum is 6 characters)');
    expect(passwordErrors('has space', 'has space')).toContain('Password must not contain spaces');
    expect(passwordErrors('secret123', 'other')).toContain("Password confirmation doesn't match with password");
    expect(passwordErrors('secret123', 'secret123')).toEqual([]);
  });
});

describe('admin TOTP', () => {
  it('accepts the current code and rejects others', () => {
    const secret = generateTotpSecret();
    expect(secret).toMatch(/^[A-Z2-7]{32}$/);
    expect(verifyTotp(currentTotp(secret), secret)).toBe(true);
    expect(verifyTotp('000000', secret) && verifyTotp('111111', secret)).toBe(false);
    expect(verifyTotp('abc', secret)).toBe(false);
  });

  it('matches codes produced by Ruby ROTP, including one step of drift behind', () => {
    // Reference codes from ROTP::TOTP.new(secret).at(1700000000) and .at(1700000000 - 30).
    const secret = 'JBSWY3DPEHPK3PXPJBSWY3DPEHPK3PXP';
    const at = 1700000000 * 1000;
    expect(verifyTotpAt('406058', secret, at)).toBe(true);
    expect(verifyTotpAt('797823', secret, at)).toBe(true);
    expect(verifyTotpAt('406058', secret, at + 60_000)).toBe(false);
  });
});
